/*
 * Optional build-time-signed AArch64 execution path for the real SoC loop.
 *
 * This file never emits executable memory. It caches decoded data records and
 * dispatches into ordinary text generated by tools/gen_a64_static.py. The
 * Product load records consult only arm_cpu's already-proved plain-RAM read
 * cache. A miss performs no access and returns to arm_step(), which remains the
 * sole owner of MMU walks, faults and MMIO. Stores remain literal because the
 * host write observer is architecturally visible to the frontend. A zero
 * return is always a clean request for the existing arm_step() path.
 */
#include "a64_static_engine.h"

#include <stdlib.h>
#include <string.h>

#if defined(S5LBOX_STATIC_A64_ENGINE)
#include "a64_static.h"

#define STATIC_A64_CACHE_ENTRIES 1024u
#define STATIC_A64_RAW_BYTES (A64_STATIC_MAX_INSNS * 4u)

typedef struct {
    const uint8_t *fetch_host;
    uint32_t pc;
    uint32_t fetch_gen;
    uint8_t raw[STATIC_A64_RAW_BYTES];
    uint8_t raw_len;
    bool fetch_priv;
    bool thumb;
    bool valid;
    bool supported;
    a64_static_block_t block;
} static_a64_entry_t;

typedef struct {
    bool enabled;
    uint64_t retired;
    static_a64_entry_t cache[STATIC_A64_CACHE_ENTRIES];
} static_a64_state_t;

static static_a64_state_t *static_state(const s5l8900_t *m) {
    return m ? (static_a64_state_t *)m->static_a64_state : NULL;
}

static unsigned cache_index(uint32_t pc, bool thumb, uint32_t generation) {
    uint32_t key = pc >> (thumb ? 1u : 2u);
    key ^= generation * UINT32_C(0x9e3779b1);
    if (thumb) key ^= UINT32_C(0x85ebca6b);
    return key & (STATIC_A64_CACHE_ENTRIES - 1u);
}

static bool entry_matches(const static_a64_entry_t *entry,
                          const arm_cpu_t *cpu, const uint8_t *bytes,
                          uint32_t pc, bool thumb, bool priv,
                          unsigned raw_len) {
    return entry->valid && entry->fetch_host == cpu->fetch_host &&
           entry->pc == pc && entry->fetch_gen == cpu->fetch_gen &&
           entry->fetch_priv == priv && entry->thumb == thumb &&
           entry->raw_len == raw_len &&
           memcmp(entry->raw, bytes, raw_len) == 0;
}

static bool decode_longest(const uint8_t *bytes, unsigned candidate_insns,
                           bool thumb, uint32_t pc,
                           a64_static_block_t *out) {
    for (unsigned count = candidate_insns; count != 0u; count--) {
        if (a64_static_decode_read_hits_bytes_at(bytes, count, thumb, pc,
                                                 out))
            return true;
    }
    return false;
}

static void decode_entry(static_a64_entry_t *entry, const arm_cpu_t *cpu,
                         const uint8_t *bytes, uint32_t pc, bool thumb,
                         bool priv, unsigned candidate_insns,
                         unsigned raw_len) {
    memset(entry, 0, sizeof *entry);
    entry->fetch_host = cpu->fetch_host;
    entry->pc = pc;
    entry->fetch_gen = cpu->fetch_gen;
    entry->fetch_priv = priv;
    entry->thumb = thumb;
    entry->raw_len = (uint8_t)raw_len;
    memcpy(entry->raw, bytes, raw_len);
    entry->valid = true;

    /* Decode the longest exact prefix. Product loads carry a guarded DREAD hit;
     * stores and unsupported forms still shorten to an earlier exact prefix. */
    if (decode_longest(bytes, candidate_insns, thumb, pc, &entry->block)) {
        entry->supported = true;
        return;
    }
}
#endif

bool s5l8900_static_a64_available(void) {
#if defined(S5LBOX_STATIC_A64_ENGINE)
    return a64_static_host_available();
#else
    return false;
#endif
}

bool s5l8900_static_a64_set_enabled(s5l8900_t *m, bool enabled) {
    if (!m) return false;
#if defined(S5LBOX_STATIC_A64_ENGINE)
    static_a64_state_t *state = static_state(m);
    if (!enabled) {
        if (state) state->enabled = false;
        return true;
    }
    if (!a64_static_host_available()) return false;
    if (!state) {
        state = (static_a64_state_t *)calloc(1u, sizeof *state);
        if (!state) return false;
        m->static_a64_state = state;
    }
    state->enabled = true;
    return true;
#else
    (void)enabled;
    return false;
#endif
}

uint64_t s5l8900_static_a64_retired(const s5l8900_t *m) {
#if defined(S5LBOX_STATIC_A64_ENGINE)
    const static_a64_state_t *state = static_state(m);
    return state ? state->retired : 0u;
#else
    (void)m;
    return 0u;
#endif
}

unsigned s5l8900_static_a64_try(s5l8900_t *m, unsigned max_insns) {
#if defined(S5LBOX_STATIC_A64_ENGINE)
    static_a64_state_t *state = static_state(m);
    arm_cpu_t *cpu;
    uint32_t pc;
    uint32_t fetch_block;
    unsigned width;
    unsigned offset;
    unsigned candidate_insns;
    unsigned raw_len;
    bool thumb;
    bool priv;
    const uint8_t *bytes;
    static_a64_entry_t *entry;
    a64_static_block_t bounded_block;
    const a64_static_block_t *run_block;
    unsigned completed = 0u;

    if (!state || !state->enabled || !max_insns ||
        !a64_static_host_available() || !m->ram || !m->ram_size ||
        (m->ram_size & (m->ram_size - 1u)) != 0u)
        return 0u;

    cpu = &m->cpu;
    if (cpu->arch != ARM_ARCH_V6_ARM1176 || !arm_mode_is_valid(cpu->cpsr) ||
        cpu->abort_pending ||
        (cpu->fiq_line && !(cpu->cpsr & ARM_CPSR_F)) ||
        (cpu->irq_line && !(cpu->cpsr & ARM_CPSR_I)))
        return 0u;

    pc = cpu->r[15];
    thumb = (cpu->cpsr & ARM_CPSR_T) != 0u;
    priv = (cpu->cpsr & ARM_CPSR_MODE_MASK) != ARM_MODE_USR;
    width = thumb ? 2u : 4u;
    if ((pc & (width - 1u)) != 0u) return 0u;

    fetch_block = pc & ~UINT32_C(0x3ff);
    if (!cpu->fetch_host || cpu->fetch_blk != fetch_block ||
        cpu->fetch_gen != cpu->tlb_gen || cpu->fetch_priv != priv)
        return 0u;

    offset = pc - fetch_block;
    candidate_insns = (0x400u - offset) / width;
    if (candidate_insns > A64_STATIC_MAX_INSNS)
        candidate_insns = A64_STATIC_MAX_INSNS;
    if (!candidate_insns) return 0u;
    raw_len = candidate_insns * width;
    bytes = cpu->fetch_host + offset;

    entry = &state->cache[cache_index(pc, thumb, cpu->fetch_gen)];
    if (!entry_matches(entry, cpu, bytes, pc, thumb, priv, raw_len))
        decode_entry(entry, cpu, bytes, pc, thumb, priv, candidate_insns,
                     raw_len);
    if (!entry->supported) return 0u;
    run_block = &entry->block;
    if (run_block->insn_count > max_insns) {
        /* The next exact device edge (or the caller's remaining budget) may
         * be nearer than the cached longest block. Decode one bounded prefix
         * instead of falling back instruction-by-instruction until the edge.
         * This occurs at most once per edge and never mutates the cache. */
        if (!decode_longest(bytes, max_insns, thumb, pc, &bounded_block))
            return 0u;
        run_block = &bounded_block;
    }

    if (!a64_static_run_read_hits(cpu, run_block, m->ram, m->ram_size,
                                  &completed)) {
        /* Fail closed, and make a transient contract mismatch re-decode rather
         * than becoming a permanent false hit. Guest state is unchanged when
         * a64_static_run_read_hits refuses a block. */
        entry->valid = false;
        return 0u;
    }
    state->retired += completed;
    return completed;
#else
    (void)m;
    (void)max_insns;
    return 0u;
#endif
}

void s5l8900_static_a64_dispose(s5l8900_t *m) {
    if (!m) return;
#if defined(S5LBOX_STATIC_A64_ENGINE)
    free(m->static_a64_state);
#endif
    m->static_a64_state = NULL;
}
